<summary>xtp_test.py (gate script, run from inside one of the pods)</summary>

```python
#!/usr/bin/env python3
"""Cross-TP secondary-tier reuse gate. Run inside the cluster.

usage: xtp_test.py SRC:port DST:port SRC_P2P_host:port N_WORDS MODE

MODE p2p: send DST the prompt with kv_transfer_params.remote_kv_source -> SRC.
          PASS requires a positive delta of the P2P tier's read bytes on DST
          (vllm:kv_offload_tiering_read_bytes_total{tier="<i>:p2p"}); FS
          reads do not count.
MODE fs:  send DST a plain request. PASS requires a positive FS-tier read
          bytes delta on DST.
Also compares DST's cached completion against an uncached baseline on DST
itself: the baseline carries a distinct cache_salt, so its block hashes
never match the shared prompt and it is computed from scratch on the same
topology. Exit status is nonzero on FAIL.
"""
import json, re, sys, time, urllib.request

SRC, DST = sys.argv[1], sys.argv[2]
SRC_P2P = sys.argv[3]
N_WORDS = int(sys.argv[4]) if len(sys.argv) > 4 else 6000
MODE = sys.argv[5] if len(sys.argv) > 5 else "p2p"
MODEL = "zai-org/GLM-5.2-FP8"
TAG = str(int(time.time()))


def post(host, body):
    req = urllib.request.Request(f"http://{host}/v1/completions", data=json.dumps(body).encode(),
                                 headers={"Content-Type": "application/json"})
    t = time.time()
    with urllib.request.urlopen(req, timeout=600) as r:
        return json.load(r), time.time() - t


def metrics(host):
    with urllib.request.urlopen(f"http://{host}/metrics", timeout=30) as r:
        txt = r.read().decode()
    out = {}
    for line in txt.splitlines():
        m = re.match(r"(vllm:[a-z_]+)(\{[^}]*\})?\s+([0-9.eE+-]+)", line)
        if m and not line.startswith("#"):
            out[m.group(1) + (m.group(2) or "")] = float(m.group(3))
    return out


def delta(before, after, name, label=None):
    def ok(k):
        return k.startswith(name) and "_created" not in k and (label is None or label in k)
    return sum(v for k, v in after.items() if ok(k)) - sum(v for k, v in before.items() if ok(k))


def tier_label(m, tier_type):
    labels = {re.search(r'tier="([^"]+)"', k).group(1) for k in m if f':{tier_type}"' in k}
    return labels.pop() if labels else None


words = ["alpha", "bravo", "charlie", "delta", "echo", "foxtrot", "golf", "hotel", "india", "juliet"]
prompt = f"run {TAG}. " + " ".join(words[i % 10] + str(i) for i in range(N_WORDS))
gen = {"model": MODEL, "max_tokens": 32, "temperature": 0}

# Uncached baseline on the destination topology: a distinct cache_salt keeps
# its block hashes disjoint from the shared prompt, so nothing is reused and
# nothing it stores can satisfy the later lookup.
rBase, tBase = post(DST, {**gen, "prompt": prompt, "cache_salt": f"baseline-{TAG}"})

m_src0, m_dst0 = metrics(SRC), metrics(DST)
rSrc, tSrc = post(SRC, {**gen, "prompt": prompt})
time.sleep(5)
m_src1 = metrics(SRC)
print(f"seed SRC: {tSrc:.2f}s prompt_tokens={rSrc['usage']['prompt_tokens']} "
      f"store_bytes_delta={delta(m_src0, m_src1, 'vllm:kv_offload_store_bytes'):.0f}")

body = {**gen, "prompt": prompt}
if MODE == "p2p":
    host, port = SRC_P2P.rsplit(":", 1)
    body["kv_transfer_params"] = {"remote_kv_source": {"kv_request_id": f"xtp-{TAG}",
                                                       "remote_host": host, "remote_port": int(port)}}
rDst, tDst = post(DST, body)
time.sleep(3)
m_dst1 = metrics(DST)

hits = delta(m_dst0, m_dst1, "vllm:external_prefix_cache_hits")
queries = delta(m_dst0, m_dst1, "vllm:external_prefix_cache_queries")
load_bytes = delta(m_dst0, m_dst1, "vllm:kv_offload_load_bytes")
per_tier = {}
for k in m_dst1:
    mm = re.match(r"vllm:kv_offload_tiering_read_bytes_total\{.*tier=\"([^\"]+)\"", k)
    if mm:
        per_tier[mm.group(1)] = delta(m_dst0, m_dst1, "vllm:kv_offload_tiering_read_bytes_total", f'tier="{mm.group(1)}"')
want = tier_label(m_dst1, MODE)
tier_read = per_tier.get(want, 0.0) if want else 0.0

print(f"{MODE} DST: {tDst:.2f}s prompt_tokens={rDst['usage']['prompt_tokens']} "
      f"external_hits={hits:.0f}/{queries:.0f} load_bytes={load_bytes:.0f}")
print(f"DST per-tier read bytes delta: {per_tier}  (gate tier: {want})")
same = rDst["choices"][0]["text"] == rBase["choices"][0]["text"]
print(f"DST cached completion == DST uncached baseline: {same}")
print("DST cached :", repr(rDst["choices"][0]["text"][:80]))
print("DST baseline:", repr(rBase["choices"][0]["text"][:80]))
print("SRC        :", repr(rSrc["choices"][0]["text"][:80]))
ok = hits > 0 and tier_read > 0
print("RESULT:", "PASS" if ok else "FAIL", f"({MODE} tier read bytes {tier_read:.0f}, hits {hits:.0f})")
sys.exit(0 if ok else 1)
```

